Chords $AB$ and $CD$ intersect inside the circle at $P$.
$AP = 6\text{ cm}$, $PB = 5\text{ cm}$ and $CP = 10\text{ cm}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.39]
\coordinate (O) at (0,0);
\coordinate (P) at (0.5,3.629);
\coordinate (A) at (-5.5,3.629);
\coordinate (B) at (5.5,3.629);
\coordinate (C) at (-3.726,-5.434);
\coordinate (D) at (1.768,6.348);
\draw (O) circle (6.589);
\fill (O) circle (1.5pt);
\node[below] at (O) {$O$};
\draw (A) -- (B);
\draw (C) -- (D);
\fill (P) circle (1.5pt);
\node[below right] at (P) {$P$};
\node[left] at (A) {$A$};
\node[right] at (B) {$B$};
\node[below] at (C) {$C$};
\node[above] at (D) {$D$};
\end{tikzpicture}
[/tikz]
Find the length of $PD$.

